t.script:
(function () {
  function fmt(n) {
    try { return (parseFloat(n) || 0).toFixed(2); } catch(e) { return '0.00'; }
  }

  function buildDetailTable(rows) {
    var html = '';
    html += '<div class="p-2">';
    html += '<table class="table table-sm table-bordered mb-0">';
    html += '<thead><tr>';
    html += '<th>Kho</th>';
    html += '<th class="text-end">Tồn khả dụng</th>';
    html += '<th class="text-end">Tồn thực tế</th>';
    html += '<th class="text-end">Đã reserve</th>';
    html += '</tr></thead><tbody>';
    if (rows && rows.length) {
      rows.forEach(function (r) {
        html += '<tr>';
        html += '<td>' + (r.warehouse_name || '') + '</td>';
        html += '<td class="text-end">' + fmt(r.qty_available) + '</td>';
        html += '<td class="text-end">' + fmt(r.qty_total) + '</td>';
        html += '<td class="text-end">' + fmt(r.qty_reserved) + '</td>';
        html += '</tr>';
      });
    } else {
      html += '<tr><td colspan="4"><em>Không có dữ liệu chi tiết.</em></td></tr>';
    }
    html += '</tbody></table></div>';
    return html;
  }

  function ensureDetailRow($tr, pid) {
    var $next = $tr.next();
    if ($next.length && $next.hasClass('detail-row')) {
      return $next;
    }
    var colCount = $tr.children('td,th').length;
    var $detail = $(
      '<tr class="detail-row bg-light"><td colspan="' + colCount + '">'+
      '<div class="d-flex align-items-center gap-2 p-2">'+
      '<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>'+
      '<span>Đang tải chi tiết kho...</span>'+
      '</div>'+
      '</td></tr>'
    );
    $tr.after($detail);
    return $detail;
  }

  function loadBreakdown(pid, warehouse_id, done) {
    var payload = {
      jsonrpc: "2.0",
      method: "call",
      params: { 
        product_id: pid, 
        warehouse_id: warehouse_id || null 
      },
      id: new Date().getTime()
    };

    console.log('Sending request:', payload);

    $.ajax({
      url: "/search_stock/product_breakdown",
      type: "POST",
      dataType: "json",
      contentType: "application/json; charset=utf-8",
      data: JSON.stringify(payload),
      success: function (resp) {
        console.log('Response received:', resp);
        try {
          var result = (resp && resp.result) ? resp.result : resp;
          done(null, result);
        } catch (e) {
          console.error('Error parsing response:', e);
          done(e);
        }
      },
      error: function (xhr, status, error) { 
        console.error('AJAX error:', status, error, xhr.responseText);
        done(xhr || true); 
      }
    });
  }

  $(document).ready(function() {
    console.log('Inventory page JS loaded');

    $(document).on('click', '.btn-expand', function () {
      var $btn = $(this);
      var pid = $btn.data('pid');
      var $row = $btn.closest('tr');
      var $next = $row.next();

      console.log('Expand button clicked for product:', pid);

      if ($next.length && $next.hasClass('detail-row') && $next.is(':visible')) {
        $next.remove();
        $btn.text('+');
        return;
      }

      var $detail = ensureDetailRow($row, pid);
      $btn.text('–');

      var currentWid = $('select[name="warehouse_id"]').val() || '';
      console.log('Current warehouse:', currentWid);

      loadBreakdown(pid, currentWid, function (err, data) {
        if (err || !data || data.ok === false) {
          var msg = (data && data.error) ? data.error : 'load_failed';
          console.error('Load breakdown error:', err, data);
          $detail.find('td').html(
            '<div class="alert alert-danger mb-0">Không tải được chi tiết (' + msg + ').</div>'
          );
          return;
        }
        console.log('Breakdown data:', data);
        var html = buildDetailTable(data.rows || []);
        $detail.find('td').html(html);
      });
    });
  });
})();
